package com.guocheng.mediapocket;
import java.net.*;import java.util.*;import java.util.regex.*;
final class TvPosterRules {
 static final Pattern MARKER=Pattern.compile("@([A-Za-z][A-Za-z0-9-]*)=");
 static final class Picture{final String url;final Map<String,String> headers;Picture(String u,Map<String,String> h){url=u;headers=h;}}
 static Picture highResolution(Picture p){try{URI u=URI.create(p.url);String host=u.getHost(),path=u.getRawPath();if(host!=null&&host.toLowerCase(Locale.ROOT).endsWith(".doubanio.com")&&u.getRawQuery()==null&&path!=null&&path.startsWith("/view/photo/s_ratio_poster/public/"))return new Picture(p.url.replace("/view/photo/s_ratio_poster/public/","/view/photo/l/public/"),p.headers);}catch(Exception ignored){}return p;}
 static List<Picture> candidates(Picture p){LinkedHashMap<String,Picture> out=new LinkedHashMap<>();Picture high=highResolution(p);try{URI u=URI.create(p.url);String host=u.getHost(),path=u.getRawPath();if(u.getRawQuery()==null&&u.getRawUserInfo()==null&&u.getPort()==-1&&("images.metahub.space".equals(host)||"live.metahub.space".equals(host))&&path!=null&&path.matches("/(poster|background|logo)/(small|medium|large)/tt[0-9]+/img")){String medium=path.replace("/small/","/medium/");String current="https://"+host+medium;out.put(current,new Picture(current,p.headers));String alternate="https://"+(host.equals("images.metahub.space")?"live.metahub.space":"images.metahub.space")+medium;out.put(alternate,new Picture(alternate,p.headers));}}catch(Exception ignored){}if(out.isEmpty())out.put(high.url,high);out.put(p.url,p);return new ArrayList<>(out.values());}
 static Picture parse(String raw){String value=raw==null?"":raw.trim();Map<String,String> headers=new LinkedHashMap<>();headers.put("User-Agent","Mozilla/5.0");if(value.startsWith("data:image/"))return new Picture(value,headers);Matcher m=MARKER.matcher(value);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> starts=new ArrayList<>(),ends=new ArrayList<>();while(m.find()){names.add(m.group(1));starts.add(m.start());ends.add(m.end());}String url=names.isEmpty()?value:value.substring(0,starts.get(0));for(int i=0;i<names.size();i++){String name=names.get(i);if(!(name.equalsIgnoreCase("Referer")||name.equalsIgnoreCase("User-Agent")||name.equalsIgnoreCase("Accept")||name.equalsIgnoreCase("Origin")))continue;String h=value.substring(ends.get(i),i+1<names.size()?starts.get(i+1):value.length());try{h=URLDecoder.decode(h,"UTF-8");}catch(Exception ignored){}if(h.indexOf('\r')>=0||h.indexOf('\n')>=0||h.indexOf('\0')>=0)throw new IllegalArgumentException("非法图片请求头");headers.put(name,h);}return new Picture(url,headers);}
 static String resolve(String base,String raw){raw=raw.trim();Picture p=parse(raw);if(p.url.startsWith("data:image/"))return raw;URI u=URI.create(base).resolve(p.url);if(!"https".equalsIgnoreCase(u.getScheme())&&!"http".equalsIgnoreCase(u.getScheme()))throw new IllegalArgumentException("图片地址类型不支持");return u.toString()+raw.substring(p.url.length());}
}
